class Lock {
    Mutex& m;
public:
    explicit Lock(Mutex& mtx) : m(mtx) { m.acquire(); }
    ~Lock() { m.release(); }
    // Rule of Five/Zero dictates non-copyable
    Lock(const Lock&) = delete;
};


// Standard Library Example: Mutex Guard
// Ensures deterministic release even under exceptions
std::mutex mtx;
void safe_operation() {
    std::lock_guard<std::mutex> lock(mtx);
    // ... thread-safe work ...
    // lock is released automatically upon return/exception.
}
